SELECT LOGICAL_AND(a) OVER (ORDER BY b), a, b
FROM (
  SELECT CAST(a AS BOOL) AS a, b FROM UNNEST([
      STRUCT(False AS a, 1 AS b),
      STRUCT(False AS a, 2 AS b),
      STRUCT(false AS a, 3 AS b),
      STRUCT(False AS a, 4 AS b)
  ])
);

SELECT LOGICAL_OR(a) OVER (ORDER BY b), a, b
FROM (
  SELECT CAST(a AS BOOL) AS a, b FROM UNNEST([
      STRUCT(False AS a, 1 AS b),
      STRUCT(False AS a, 2 AS b),
      STRUCT(True AS a, 3 AS b),
      STRUCT(False AS a, 4 AS b)
  ])
);

WITH produce AS (select 'lettuce' AS item UNION ALL SELECT 'banana')
SELECT item, in_stock_items is not null AS item_in_stock FROM produce
LEFT OUTER JOIN unnest(['lettuce']) in_stock_items ON in_stock_items = item;

WITH produce AS (select 'lettuce' AS item UNION ALL SELECT 'banana')
SELECT item, in_stock_items is not null AS item_in_stock FROM produce
INNER JOIN unnest(['lettuce']) in_stock_items ON in_stock_items = item;

WITH produce AS (SELECT 'banana' AS item, 3 AS purchases),
toks AS (
	SELECT item FROM (
		SELECT * FROM produce
		WHERE item = 'banana'
	) sub
	WHERE purchases = 3
)
SELECT * FROM toks;

